import { describe, expect, it } from "vitest";
import { groupEventsByToolCall } from "../try-assistant/ConversationLog/groupEventsByToolCall";
import {
  ConversationEventType,
  type Conversation,
  type ConversationEvent,
  type LlmCallRecord,
} from "../types";
import { mergeLlmCallsIntoConversations } from "./llm-calls";

function makeRecord(overrides: Partial<LlmCallRecord>): LlmCallRecord {
  return {
    id: "r1",
    timestamp: 100,
    purpose: null,
    request_model: "gpt-4o",
    response_model: null,
    input_tokens: null,
    output_tokens: null,
    latency_ms: 250,
    time_to_first_token_ms: null,
    tool_names: [],
    gated_tool_names: [],
    response_tool_names: [],
    prompt_messages: null,
    response_messages: null,
    is_error: false,
    error_message: null,
    ...overrides,
  };
}

function makeEvent(
  id: string,
  originalTimestamp: number,
  overrides: Partial<ConversationEvent> = {},
): ConversationEvent {
  return {
    id,
    conversationEventType: ConversationEventType.FlowStarted,
    name: "flow_started",
    actionText: "",
    flowId: "f",
    stepId: "",
    slotValue: null,
    timestamp: new Date(originalTimestamp * 1000).toISOString(),
    originalTimestamp,
    metadata: { parseData: undefined },
    __typename: "ConversationEvent",
    ...overrides,
  };
}

function makeConversation(id: string, events: ConversationEvent[]): Conversation {
  return {
    id,
    events,
    startDate: new Date().toISOString(),
    totalNumberOfUserMessages: 1,
  } as Conversation;
}

describe("mergeLlmCallsIntoConversations", () => {
  it("inserts a call before the events it caused", () => {
    const conversations = [makeConversation("c1", [makeEvent("e1", 90), makeEvent("e2", 110)])];
    const merged = mergeLlmCallsIntoConversations(conversations, [
      makeRecord({ id: "r1", timestamp: 100 }),
    ]);
    expect(merged[0].events.map((event) => event.id)).toEqual(["e1", "llm-call-r1", "e2"]);
    expect((merged[0].events[1] as ConversationEvent).conversationEventType).toBe(
      ConversationEventType.LlmCallRecorded,
    );
  });

  it("appends calls newer than every event", () => {
    const conversations = [makeConversation("c1", [makeEvent("e1", 90)])];
    const merged = mergeLlmCallsIntoConversations(conversations, [
      makeRecord({ id: "r1", timestamp: 200 }),
    ]);
    expect(merged[0].events.map((event) => event.id)).toEqual(["e1", "llm-call-r1"]);
  });

  it("assigns calls to the conversation covering their timestamp", () => {
    const conversations = [
      makeConversation("c1", [makeEvent("e1", 100)]),
      makeConversation("c2", [makeEvent("e2", 200)]),
    ];
    const merged = mergeLlmCallsIntoConversations(conversations, [
      makeRecord({ id: "old", timestamp: 150 }),
      makeRecord({ id: "new", timestamp: 250 }),
    ]);
    expect(merged[0].events.map((event) => event.id)).toEqual(["e1", "llm-call-old"]);
    expect(merged[1].events.map((event) => event.id)).toEqual(["e2", "llm-call-new"]);
  });

  it("returns the input untouched without calls", () => {
    const conversations = [makeConversation("c1", [makeEvent("e1", 90)])];
    expect(mergeLlmCallsIntoConversations(conversations, [])).toBe(conversations);
  });

  it("drops calls older than the first known conversation", () => {
    const conversations = [makeConversation("c1", [makeEvent("e1", 100)])];
    const merged = mergeLlmCallsIntoConversations(conversations, [
      makeRecord({ id: "stale", timestamp: 50 }),
    ]);
    expect(merged[0].events.map((event) => event.id)).toEqual(["e1"]);
  });

  it("keeps the input order of calls falling between the same two events", () => {
    const conversations = [makeConversation("c1", [makeEvent("e1", 90), makeEvent("e2", 200)])];
    const merged = mergeLlmCallsIntoConversations(conversations, [
      makeRecord({ id: "first", timestamp: 100 }),
      makeRecord({ id: "second", timestamp: 120 }),
    ]);
    expect(merged[0].events.map((event) => event.id)).toEqual([
      "e1",
      "llm-call-first",
      "llm-call-second",
      "e2",
    ]);
  });

  it("inserts a call after the event sharing its timestamp", () => {
    // Pins the current strict-> insertion; equal-timestamp semantics are under discussion.
    const conversations = [
      makeConversation("c1", [makeEvent("e1", 90), makeEvent("e2", 100), makeEvent("e3", 110)]),
    ];
    const merged = mergeLlmCallsIntoConversations(conversations, [
      makeRecord({ id: "tied", timestamp: 100 }),
    ]);
    expect(merged[0].events.map((event) => event.id)).toEqual(["e1", "e2", "llm-call-tied", "e3"]);
  });
});

describe("merged conversations feeding groupEventsByToolCall", () => {
  it("groups a merged fact-discovery call with the __discovered__ write it caused", () => {
    const discoveredWrite = makeEvent("w1", 110, {
      conversationEventType: ConversationEventType.Slot,
      name: "facts.__discovered__",
    });
    const conversations = [makeConversation("c1", [makeEvent("e1", 90), discoveredWrite])];
    const merged = mergeLlmCallsIntoConversations(conversations, [
      makeRecord({ id: "fd", timestamp: 100, purpose: "fact discovery" }),
    ]);

    const items = groupEventsByToolCall(merged[0].events);

    expect(items.map((item) => item.kind)).toEqual(["event", "llm-group"]);
    const group = items[1];
    if (group.kind !== "llm-group") throw new Error("expected an llm-group");
    expect(group.call.id).toBe("llm-call-fd");
    expect(group.children.map((child) => child.id)).toEqual(["w1"]);
  });
});
